node -e '
const LOCK_BUSY_RE = /DataDirLockedError|another process holds the lock|Resource temporarily unavailable|_acquire_lock|fcntl\.flock/i;
const cases = [
  ["REAL hook failure from .errors.log", "Failed to start MilvusLite server for /Users/kristinarash/.memsearch/milvus.db\nTraceback (most recent call last):\n  File \".../milvus_lite/db.py\", line 932, in _acquire_lock\n    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)", true],
  ["REAL stats failure seen earlier", "milvus_lite.exceptions.DataDirLockedError: another process holds the lock on /Users/kristinarash/.memsearch/milvus.db: [Errno 35] Resource temporarily unavailable", true],
  ["AMBIGUOUS corruption wording alone", "RuntimeError: Failed to open the local Milvus Lite database. If this database was created with an older Milvus Lite release, it may not be compatible with Milvus Lite 3.x.", false],
  ["Unrelated failure", "MemoryError: cannot allocate embedding batch", false],
];
let pass=0;
for (const [name, text, want] of cases) {
  const got = LOCK_BUSY_RE.test(text);
  const ok = got === want;
  if (ok) pass++;
  console.log((ok?"PASS":"FAIL") + "  " + name + "  -> transient=" + got + " (expected " + want + ")");
}
console.log("\n" + pass + "/" + cases.length + " passed");
'

